create sequence if not exists public.quotation_number_seq as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

-- -- tables ------------------------------------------------------
create table if not exists public.deals (
  id uuid not null,
  client_id uuid,
  title character varying(240) not null,
  stage character varying(40) not null,
  expected_value numeric(15,2) not null,
  assigned_to uuid,
  notes text,
  production_order_id uuid,
  created_at timestamp with time zone not null,
  updated_at timestamp with time zone not null
);

create table if not exists public.quotations (
  id uuid not null,
  deal_id uuid not null,
  quote_number character varying(40) not null,
  total_amount numeric(15,2) not null,
  discount numeric(15,2) not null,
  tax numeric(15,2) not null,
  valid_until date,
  status character varying(20) not null,
  items_json jsonb not null,
  notes text,
  production_order_id uuid,
  created_by uuid,
  created_at timestamp with time zone not null,
  updated_at timestamp with time zone not null
);


